-- 13-play-details. Reviewed uploaded workbook only; save pending edits and back up first.
-- Run ENTIRE file in DB Browser, verify counts, then Write Changes.
-- SAVEPOINT supports an existing transaction. No records are replaced.
-- Raw payloads, logs and fatigue recovery retained; unknown historical animation/clock stays NULL.
PRAGMA foreign_keys=ON;
SAVEPOINT afl_remaining_13;
CREATE TEMP TABLE afl_remaining_13_0 AS SELECT play_id, defense_predicted, prediction_correct, ol_wins, ol_losses, dl_wins, dl_losses, jukes, trucks, broken_tackles, stop_reason, run_log_json, fatigue_recovery_json, animation_json, resolution_audit_json, original_payload_json FROM play_details WHERE 0;
CREATE TEMP TABLE afl_remaining_13_guard(ok INTEGER);
CREATE TEMP TRIGGER afl_remaining_13_check BEFORE INSERT ON afl_remaining_13_guard
BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM leagues WHERE id='36c6e53f-7be2-5a94-84a8-0df871aae9fd' AND name='AFL') THEN RAISE(ROLLBACK,'Missing AFL league.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM seasons WHERE id='97808f43-a0d5-5251-bf8d-fae1643c8258' AND league_id='36c6e53f-7be2-5a94-84a8-0df871aae9fd') THEN RAISE(ROLLBACK,'Import 05 season first.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM schema_migrations WHERE version=2) THEN RAISE(ROLLBACK,'Apply schema upgrade 10 first.') END;
 SELECT CASE WHEN (SELECT count(*) FROM plays WHERE game_id IN (SELECT id FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258'))<>9575 THEN RAISE(ROLLBACK,'Import all official plays (12) first.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_13_0 i JOIN play_details t ON t.play_id=i.play_id WHERE t.defense_predicted IS NOT i.defense_predicted OR t.prediction_correct IS NOT i.prediction_correct OR t.ol_wins IS NOT i.ol_wins OR t.ol_losses IS NOT i.ol_losses OR t.dl_wins IS NOT i.dl_wins OR t.dl_losses IS NOT i.dl_losses OR t.jukes IS NOT i.jukes OR t.trucks IS NOT i.trucks OR t.broken_tackles IS NOT i.broken_tackles OR t.stop_reason IS NOT i.stop_reason OR t.run_log_json IS NOT i.run_log_json OR t.fatigue_recovery_json IS NOT i.fatigue_recovery_json OR t.animation_json IS NOT i.animation_json OR t.resolution_audit_json IS NOT i.resolution_audit_json OR t.original_payload_json IS NOT i.original_payload_json) THEN RAISE(ROLLBACK,'play_details: existing record differs; no overwrite.') END;
END;
DROP TRIGGER afl_remaining_13_check;
DROP TABLE afl_remaining_13_guard;
DROP TABLE afl_remaining_13_0;
RELEASE SAVEPOINT afl_remaining_13;
PRAGMA foreign_key_check;
SELECT 'play_details' AS imported_table,count(*) AS reviewed_records_present FROM play_details t WHERE EXISTS(SELECT 1 FROM source_record_mappings m WHERE m.import_batch_id='6dcc85e7-6173-5f59-938e-b77a7bd54a46' AND m.target_table='play_details' AND m.target_id=CAST(t.play_id AS TEXT));
